function moonSign(dt) {
  var jd = dt.getTime() / 864e5 + 2440587.5, T = (jd - 2451545) / 36525, r = Math.PI / 180;
  var L = 218.3164477 + 481267.88123421 * T, D = 297.8501921 + 445267.1114034 * T, M = 357.5291092 + 35999.0502909 * T, Mp = 134.9633964 + 477198.8675055 * T, F = 93.272095 + 483202.0175233 * T;
  var lon = L + 6.289 * Math.sin(Mp * r) + 1.274 * Math.sin((2 * D - Mp) * r) + 0.658 * Math.sin(2 * D * r) + 0.214 * Math.sin(2 * Mp * r) - 0.186 * Math.sin(M * r) - 0.114 * Math.sin(2 * F * r);
  var ay = 23.85 + (dt.getUTCFullYear() - 2000) * 0.01397;
  return Math.floor((((lon - ay) % 360) + 360) % 360 / 30);
}
