function daily(nm, bw, bs) {
  var td = today(), now = new Date(), wd = new Date(td + 'T12:00:00+07:00').getDay();
  var ms = moonSign(new Date(td + 'T07:00:00+07:00')), R = rng(hash(td + '|' + nm));
  var deck = []; for (var i = 1; i <= 36; i++) deck.push(i);
  for (var j = 35; j > 0; j--) { var k = Math.floor(R() * (j + 1)), t = deck[j]; deck[j] = deck[k]; deck[k] = t; }
  var c = deck.slice(0, 3), ti = tier(bw, bs, ms, wd);
  var bp = bw >= 0 ? planetOfDay(bw) : planetOfDay(wd), ix = tqIdx(bp);
  var sri = TQ[(ix + 3) % 8], dech = TQ[(ix + 2) % 8];
  return {
    ms: ms, c: c, ti: ti,
    ov: pick(R, TXT.ov[ti]), cr: pick(R, TXT.cr[ti]), wk: pick(R, TXT.wk[ti]), lv: pick(R, TXT.lv[ti]),
    num: [dech, sri].join(' · '), dir: PDIR[sri], time: pick(R, TIMES),
    col: PCOL[sri], col2: PCOL[dech], merit: MERIT[bw >= 0 ? bw : wd], buddha: BUDDHA[bw >= 0 ? bw : wd], carry: (function (x) { return x === 'ผ้าเช็ดหน้าสี' ? x + PCOL[sri] : x; })(pick(R, CARRY))
  };
}
